-- Reference catalogs. Country names: GeoNames/Unicode; Colombian locations: DANE DIVIPOLA.
create table public.countries(code text primary key check(length(code)=2),name text not null);
create table public.regions(code text primary key,country_code text not null references public.countries(code),name text not null,unique(country_code,name));
create table public.cities(code text primary key,region_code text not null references public.regions(code),country_code text not null references public.countries(code),name text not null,latitude double precision,longitude double precision);
create index cities_region_name_idx on public.cities(region_code,name);
create table public.currencies(code text primary key,name text not null,symbol text not null,sort_order integer not null);
insert into public.currencies values('COP','Peso colombiano','$',0),('USD','Dólar estadounidense','US$',1),('EUR','Euro','€',2),('GBP','Libra esterlina','£',3),('MXN','Peso mexicano','MX$',4),('BRL','Real brasileño','R$',5),('CAD','Dólar canadiense','CA$',6),('AUD','Dólar australiano','A$',7),('JPY','Yen japonés','¥',8),('CHF','Franco suizo','CHF',9),('CNY','Yuan chino','CN¥',10),('PEN','Sol peruano','S/',11),('CLP','Peso chileno','CL$',12),('ARS','Peso argentino','AR$',13);
create table public.plan_categories(name text primary key,label text not null,sort_order integer not null);
insert into public.plan_categories values('Aventura','Aventura',0),('Cultura','Cultura',1),('Gastronomía','Comida y café',2),('Naturaleza','Naturaleza',3),('Bienestar','Bienestar',4),('Deporte','Deporte',5),('Arte','Arte',6),('Música','Música',7),('Nocturno','Vida nocturna',8),('Familia','En familia',9),('Talleres','Talleres',10),('Rural','Turismo rural',11),('Historia','Historia',12),('Otro','Otros planes',13);
do $$declare t text;begin foreach t in array array['countries','regions','cities','currencies','plan_categories'] loop execute format('alter table public.%I enable row level security',t);execute format('grant select on public.%I to anon,authenticated',t);execute format('create policy catalog_read on public.%I for select to anon,authenticated using(true)',t);end loop;end $$;
