alter table public.profiles add column country_code text references public.countries(code),add column region_code text references public.regions(code),add column city_code text references public.cities(code),add column preferred_currency text not null default 'COP' references public.currencies(code),add column interests text[] not null default '{}';
grant update(country_code,region_code,city_code,preferred_currency,interests) on public.profiles to authenticated;
create function private.validate_profile_location() returns trigger language plpgsql set search_path='' as $$
begin
 if new.country_code is not null then select c.name into new.country from public.countries c where c.code=new.country_code;end if;
 if new.region_code is not null and not exists(select 1 from public.regions r where r.code=new.region_code and r.country_code=new.country_code) then raise exception 'El departamento no corresponde al país';end if;
 if new.city_code is not null then
   if not exists(select 1 from public.cities c where c.code=new.city_code and c.country_code=new.country_code and c.region_code=new.region_code) then raise exception 'La ciudad no corresponde al departamento';end if;
   select c.name into new.city from public.cities c where c.code=new.city_code;
 end if;
 if new.country_code='CO' and (new.region_code is null or new.city_code is null) then raise exception 'Selecciona departamento y municipio';end if;
 if cardinality(new.interests)>8 then raise exception 'Elige hasta 8 intereses';end if;
 return new;
end $$;
create trigger profile_location before update of country_code,region_code,city_code,interests on public.profiles for each row execute function private.validate_profile_location();
create table public.profile_photos(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,url text not null,created_at timestamptz not null default now());
create index profile_photos_user_idx on public.profile_photos(user_id,created_at desc);
alter table public.profile_photos enable row level security;
grant select,delete on public.profile_photos to authenticated;
grant insert(user_id,url) on public.profile_photos to authenticated;
create policy photos_own on public.profile_photos for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create function private.validate_profile_photo() returns trigger language plpgsql set search_path='' as $$begin
 perform 1 from public.profiles where id=new.user_id for update;
 if (select count(*) from public.profile_photos where user_id=new.user_id)>=24 then raise exception 'Puedes guardar hasta 24 fotos';end if;
 return new;
end $$;
create trigger photo_limit before insert on public.profile_photos for each row execute function private.validate_profile_photo();
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('user-media','user-media',true,4194304,array['image/webp','image/jpeg','image/png']) on conflict(id) do nothing;
create policy media_insert_own on storage.objects for insert to authenticated with check(bucket_id='user-media' and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy media_select_own on storage.objects for select to authenticated using(bucket_id='user-media' and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy media_delete_own on storage.objects for delete to authenticated using(bucket_id='user-media' and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy media_update_own on storage.objects for update to authenticated using(bucket_id='user-media' and (storage.foldername(name))[1]=(select auth.uid())::text) with check(bucket_id='user-media' and (storage.foldername(name))[1]=(select auth.uid())::text);
alter table public.experiences drop constraint experiences_category_check;
alter table public.experiences add constraint experiences_primary_category_fk foreign key(category) references public.plan_categories(name);
alter table public.experiences add column categories text[] not null default '{}';
update public.experiences set categories=array[category];
create function private.validate_plan_categories() returns trigger language plpgsql set search_path='' as $$begin
 if cardinality(new.categories)=0 then new.categories:=array[new.category];end if;
 if cardinality(new.categories)>6 or exists(select 1 from unnest(new.categories) c where not exists(select 1 from public.plan_categories p where p.name=c)) then raise exception 'Elige de 1 a 6 categorías válidas';end if;
 new.category:=new.categories[1];return new;
end $$;
create trigger validate_categories before insert or update of categories on public.experiences for each row execute function private.validate_plan_categories();
alter function private.host_action(text,jsonb) rename to host_action_base;
create function private.host_action(action text,payload jsonb) returns jsonb language plpgsql security invoker set search_path='' as $$
declare result jsonb; selected_categories text[];
begin
 if action='save_experience' and payload ? 'categories' then
   select array_agg(value) into selected_categories from jsonb_array_elements_text(payload->'categories');
   if coalesce(cardinality(selected_categories),0) not between 1 and 6 then raise exception 'Elige de 1 a 6 categorías';end if;
   payload:=jsonb_set(payload,'category',to_jsonb(selected_categories[1]));
 end if;
 result:=private.host_action_base(action,payload);
 if action='save_experience' and selected_categories is not null then
   -- The existing privileged workflow already validated ownership. Use a narrow helper.
   perform private.set_plan_categories((result->>'id')::uuid,selected_categories);
 end if;
 return result;
end $$;
revoke all on function private.host_action(text,jsonb) from public,anon;
grant execute on function private.host_action(text,jsonb) to authenticated;
create function private.set_plan_categories(plan_id uuid,selected_categories text[]) returns void language plpgsql security definer set search_path='' as $$begin
 if not private.has_role((select auth.uid()),'host') or not exists(select 1 from public.experiences e join public.host_profiles h on h.id=e.host_profile_id where e.id=plan_id and h.owner_id=(select auth.uid()) and h.approved_at is not null) then raise exception 'Sin permisos';end if;
 update public.experiences set categories=selected_categories where id=plan_id;
end $$;
revoke all on function private.set_plan_categories(uuid,text[]) from public,anon;
grant execute on function private.set_plan_categories(uuid,text[]) to authenticated;
create or replace view public.experience_feed with (security_invoker=true) as
select e.id,e.host_profile_id as provider_id,h.display_name as provider,h.handle as provider_handle,e.title,e.short_description,e.description,e.location_label as location,e.category,e.price_amount,e.currency,e.duration_minutes,e.maximum_people as max_people,e.meeting_point,e.latitude,e.longitude,e.includes,e.requirements,e.age_policy,e.minimum_age,e.minors_supervision_required,e.age_policy_note,e.status,e.published_at,
 coalesce((select array_agg(i.image_url order by i.position) from public.experience_images i where i.experience_id=e.id),'{}'::text[]) as images,
 coalesce((select count(*) from public.reviews r where r.experience_id=e.id and r.status='published'),0)::integer as reviews_count,
 (select avg(r.experience_score)::numeric(3,2) from public.reviews r where r.experience_id=e.id and r.status='published') as experience_rating_score,
 (select avg(r.host_score)::numeric(3,2) from public.reviews r where r.host_profile_id=e.host_profile_id and r.status='published') as host_rating_score,
 (select count(*) from public.experience_likes l where l.experience_id=e.id)::integer as likes_count,
 (select count(*) from public.experience_comments c where c.experience_id=e.id)::integer as comments_count,
 exists(select 1 from public.experience_likes l where l.experience_id=e.id and l.user_id=(select auth.uid())) as is_liked_by_me,
 private.is_experience_saved(e.id) as is_saved_by_me, e.categories
from public.experiences e join public.host_profiles h on h.id=e.host_profile_id where e.status='published' and (e.is_demo or h.approved_at is not null);

